// === lib/models/task_model.dart ===
class TaskModel {
  final int id;
  String title;
  bool isFavorite;
  TaskStatus status;

  factory TaskModel.fromJson(Map<String, dynamic> json) {
    return TaskModel(
      id: json['id'] as int,
      title: json['title'] as String,
      isFavorite: json['isFavorite'] as bool? ?? false,
      status: json['status'] == 'done' ? TaskStatus.done : TaskStatus.active,
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'id': id,
      'title': title,
      'isFavorite': isFavorite,
      'status': status.name,
    };
  }
}

// === lib/services/task_storage_service.dart (фрагмент) ===
class TaskStorageService {
  static const String assetPath = 'assets/data/tasks.json';
  static const String localFileName = 'tasks.json';

  Future<String> readJsonFromAssets() async {
    return await rootBundle.loadString(assetPath);
  }

  Future<File> _getLocalFile() async {
    final directory = await getApplicationDocumentsDirectory();
    return File('${directory.path}/$localFileName');
  }

  Future<List<TaskModel>> loadTasks() async {
    // ... (пропуск неістотних рядків)
    final assetJson = await readJsonFromAssets();
    final tasks = tasksFromJson(assetJson);
    await saveTasks(tasks);
    return tasks;
  }

  Future<void> saveTasks(List<TaskModel> tasks) async {
    final file = await _getLocalFile();
    file.writeAsStringSync(tasksToJson(tasks), flush: true);
  }
}

// === lib/screens/lab7_screen.dart (фрагмент) ===
  Future<void> _loadTasksFromJson() async {
    final loadedTasks = await _storageService.loadTasks();
    if (mounted) {
      setState(() {
        _tasks = loadedTasks;
        _isLoading = false;
      });
    }
  }

  Future<void> _persistTasks() async {
    await _storageService.saveTasks(_tasks);
  }
